import{_ as n,l as t,o as e,c as p,v as r,p as l,x as i,d as E,i as d,S as B}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Combinatorial Purged CV","description":"","frontmatter":{"title":"Combinatorial Purged CV","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cpcv-lopez.md","filePath":"quant/cpcv-lopez.md","lastUpdated":1789023840000}'),h={name:"quant/cpcv-lopez.md"};function s(c,a,A,u,m,C){const o=t("Mermaid");return e(),p("div",null,[a[1]||(a[1]=r('<h1 id="combinatorial-purged-cv" tabindex="-1">Combinatorial Purged CV <a class="header-anchor" href="#combinatorial-purged-cv" aria-label="Permalink to &quot;Combinatorial Purged CV&quot;">​</a></h1><div class="epigraph"><p>单条回测路径是一次历史实现；把样本切成 $N$ 组、对测试组做组合，可以在同一段历史上生成许多条经过清洗的样本外路径，从而看到评估本身的分布。</p><footer>—— López de Prado, Advances in Financial Machine Learning, Chapter 12, 2018</footer></div><p><a href="/quant/imbalance-bars">上一课</a>按活动量切片减轻墙钟等权造成的异方差，不平衡 bar 在成交符号累积超出期望时封口。缺口是验证：walk-forward 只给出一条拼接的样本外曲线，看不到切分稍有不同时点估计会散成什么样。<a href="/quant/cpcv">组合过拟合 CPCV</a> 一文从 PBO 出发；AFML 的 Combinatorial Purged CV 还有另一半——对已经冻结的估计器，生成许多条样本外预测路径。本课写组数 \\(N\\)、每组测试块数 \\(k\\)、路径条数如何计数、每条路径上如何 purge。不把 bar 的封口规则再讲一遍，也不把 CPCV 再讲成优化器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Walk-forward 尊重时间箭头，但只给出一条（或很少几条）拼接的样本外曲线。窗口个数往往是十几，相邻窗口还共享波动状态。你看到的夏普是这条路径的点估计，看不到「若切分稍有不同，点估计会散成什么样」。普通 \\(K\\) 折给出 \\(K\\) 段折外，却破坏时间，且金融标签重叠会泄漏，见<a href="/quant/cv-leakage-finance">交叉验证泄漏</a>。需要一种划分：每一段历史都有机会当测试，测试段的训练标签被清洗，并且测试结果可以拼成<strong>覆盖全样本的多条路径</strong>，而不是 \\(K\\) 个碎片。</p><p>López de Prado 的构造是：把 \\(T\\) 个观测按时间分成 \\(N\\) 个连续组（groups）。每一次划分选取其中 \\(k\\) 个组当测试、其余 \\(N-k\\) 个当训练，测试组不必相邻。全部组合有 \\(\\binom{N}{k}\\) 种。每种组合在清洗后的训练集上拟合一次，在该组合的测试组上预测。于是每个组会在许多种组合里当测试，得到多套折外预测。再按规则把这些预测对齐成若干条完整路径。问题从「报告一条 OOS 夏普」变成「报告 OOS 夏普的经验分布」。</p><h3 id="路径条数不是组合数" tabindex="-1">路径条数不是组合数 <a class="header-anchor" href="#路径条数不是组合数" aria-label="Permalink to &quot;路径条数不是组合数&quot;">​</a></h3><p>组合数是 \\(\\binom{N}{k}\\)。每个组出现在测试中的次数是 \\(\\binom{N-1}{k-1}\\)。一条完整路径需要对每个组选取一次「当它是测试组时」的预测。可以证明，能够对齐出来的路径数是</p> \\[\\varphi=\\binom{N-1}{k-1}=\\frac{k}{N}\\binom{N}{k}. \\]<p>例如 \\(N=6,k=2\\)，\\(\\binom{6}{2}=15\\) 种划分，\\(\\varphi=5\\) 条路径。每条路径仍覆盖全部 \\(N\\) 组的时间，但每组上的预测来自不同的训练补集。\\(\\varphi\\) 才是你用来画分布的样本路径数；把 15 种划分的夏普当 15 条独立回测，会重复使用同一段测试、高估精度。</p><p><span class="marginnote">\\(k=1\\) 时 CPCV 退化为 purged \\(K\\)-fold：\\(\\varphi=1\\)，只有一条由 \\(N\\) 段折外拼成的路径。要看到分布，必须 \\(k\\ge 2\\)。这是组合验证相对普通 \\(K\\) 折的全部意义所在。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选定 \\(N,k\\) 使 \\(\\varphi\\) 足够大、而每次训练仍留有 \\(N-k\\) 组。对每一个组合 \\(c\\)：测试索引为所选 \\(k\\) 组；训练索引为其余组再减去与测试标签重叠的样本（purge），并在每个测试块结束后禁运一段（embargo），细节见 <a href="/quant/purge-embargo">Embargo 与 Purge</a>。在清洗后的训练索引上拟合预处理与模型，对测试索引预测。把预测写入一张「观测 × 路径」的表：同一观测在 \\(\\varphi\\) 条路径里各有一个折外预测（来自不同组合里该观测所在组当测试的那些次）。</p><p>绩效在<strong>路径维</strong>上算：每一列是一条完整的样本外收益或预测序列，得到 \\(\\varphi\\) 个夏普、\\(\\varphi\\) 个最大回撤。报告中位数、分位、以及最差路径，而不是报告最好路径。若还要一条可叙述的因果曲线，另外跑预先声明的 walk-forward，不要从 \\(\\varphi\\) 条里挑最好的那条充当「样本外」。</p><h3 id="与-pbo-的接口" tabindex="-1">与 PBO 的接口 <a class="header-anchor" href="#与-pbo-的接口" aria-label="Permalink to &quot;与 PBO 的接口&quot;">​</a></h3><p>PBO 需要 \\(M\\) 个候选：在每个划分的训练块上选冠军，看冠军在测试块上的相对排名。<a href="/quant/cpcv">cpcv.md</a> 写的是这件事。本章的路径分布针对 \\(M=1\\)：它回答「这个冻结的估计器在不同训练补集下有多稳」，不回答「你搜过的集合是否过拟合」。两者应串联：先用带 PBO 的组合实验看搜索过程，再对晋级的那一个估计器做本章的路径分布，最后用 <a href="/quant/deflated-sharpe">DSR</a> 把尝试次数写进夏普的检验。跳过第一层、只用路径中位数当选模标准，等于把 \\(\\varphi\\) 条路径又变成一次选择。</p><p>计算上 \\(\\binom{N}{k}\\) 次拟合必须向量化。订单级回测跑不了这么多次时，应在研究层用同一套标签与成本模型评分，晋级后再对冻结候选做少量事件级模拟。评分函数若含全样本标准化，组合次数只是把泄漏复制 \\(\\binom{N}{k}\\) 遍。</p><p><span class="marginnote">交错的测试组使部分路径在时间上不是「先训练后交易」的部署顺序。这些路径合法地用于估计评估不确定性，不合法地用于估计冲击与容量。可部署性仍以因果滚动为准。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每条路径对应一种「哪些历史被拿去训练、哪些被拿来考试」的选择。真实技能在多数训练补集下仍应给出同类预测；过拟合于某段噪声的模型，一旦该段被拿去测试、训练里没了这段，绩效会塌。路径分布的离散度因此是<strong>划分敏感性</strong>的估计。它不能创造新的历史：\\(\\varphi\\) 条路径高度依赖同一段噪声实现，三年数据上的窄分位并不等于三年外的保证。</p><p>与 CSCV 的对称一半对一半相比，CPCV 的 \\(k\\) 可调：测试块更少则每次训练更充分、更像部署，但 \\(\\varphi\\) 的解释变成「在较厚的训练集上换较薄的测试块」；测试块更多则更接近 Bailey 的对称设计，训练更饿。没有 universally 最优的 \\((N,k)\\)。预先冻结，并报告一组邻近值的敏感性，而不是看完分布再选 \\(\\varphi\\) 最大的那个。</p><h3 id="每个观测的多预测不是集成指令" tabindex="-1">每个观测的多预测不是集成指令 <a class="header-anchor" href="#每个观测的多预测不是集成指令" aria-label="Permalink to &quot;每个观测的多预测不是集成指令&quot;">​</a></h3><p>同一 \\(t\\) 上有 \\(\\varphi\\) 个折外预测，可以用来看该 \\(t\\) 上预测的稳定度，但不要把它们平均成一个「更聪明」的信号再交易——那是在用测试期的多个模型做事后集成，部署时你没有这些平行宇宙。路径是评估用的，不是新的 alpha。若要集成，必须定义一种不看测试标签的规则（例如只平均当时已经拟合完成的模型），并单独走一遍验证。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>CPCV 不替代成本、容量与非平稳。路径中位数好看而因果滚动失败，通常是交错划分平均掉了体制顺序。反过来，滚动好看而路径分布极宽，说明你看到的滚动夏普高度依赖窗口。两者都要报。\\(N\\) 太大则每组太短，purge 之后训练集空洞；\\(N\\) 太小则 \\(\\varphi\\) 不够。标签很长时，先缩短标签或加长组，不要取消清洗。</p><p>候选一旦因看到路径分布而增删，分布作废，必须回到 PBO 那一层重新冻结集合。这与「在验证集上早停后再把验证曲线当样本外」是同一类错误。</p><p><span class="marginnote">AFML 把回测定义为对无偏评估器的输入。CPCV 的输出是分布；研报标题若只摘上分位，组合验证就被降级成又一次选美。</span></p>',27)),(e(),l(B,null,{default:i(()=>[d(o,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E6%97%B6%E9%97%B4%E4%B8%8A%20N%20%E4%B8%AA%E8%BF%9E%E7%BB%AD%E7%BB%84%22%5D%20--%3E%20COMB%5B%22%E5%85%A8%E9%83%A8%20C(N%2Ck)%20%E7%A7%8D%3A%20k%20%E7%BB%84%E6%B5%8B%E8%AF%95%22%5D%0A%20%20COMB%20--%3E%20PE%5B%22%E6%AF%8F%E6%9D%A1%E5%88%92%E5%88%86%3A%20purge%20%2B%20embargo%22%5D%0A%20%20PE%20--%3E%20FIT%5B%22%E4%BB%85%E5%9C%A8%E6%B8%85%E6%B4%97%E5%90%8E%E8%AE%AD%E7%BB%83%E7%BB%84%E4%B8%8A%E6%8B%9F%E5%90%88%22%5D%0A%20%20FIT%20--%3E%20PRED%5B%22%E5%9C%A8%E6%B5%8B%E8%AF%95%E7%BB%84%E4%B8%8A%E9%A2%84%E6%B5%8B%22%5D%0A%20%20PRED%20--%3E%20PATH%5B%22%E5%AF%B9%E9%BD%90%E6%88%90%20%CF%86%20%3D%20C(N-1%2C%20k-1)%20%E6%9D%A1%E5%AE%8C%E6%95%B4%E8%B7%AF%E5%BE%84%22%5D%0A%20%20PATH%20--%3E%20DIST%5B%22%E8%B7%AF%E5%BE%84%E4%B8%8A%E7%9A%84%20OOS%20%E7%BB%A9%E6%95%88%E5%88%86%E5%B8%83%22%5D%0A%20%20DIST%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%E4%B8%AD%E4%BD%8D%E6%95%B0%E4%B8%8E%E5%88%86%E4%BD%8D%2C%20%E4%B8%8D%E6%91%98%E6%9C%80%E5%A4%A7%E5%80%BC%22%5D%0A%20%20WF%5B%22%E9%A2%84%E5%85%88%E5%A3%B0%E6%98%8E%E7%9A%84%E5%9B%A0%E6%9E%9C%E6%BB%9A%E5%8A%A8%22%5D%20--%3E%20REP%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AFML 第 12 章的 CPCV 用 \\(\\binom{N}{k}\\) 种划分、对齐成 \\(\\varphi=\\binom{N-1}{k-1}\\) 条清洗后的完整样本外路径，用来估计单个估计器的划分敏感性。</li><li>\\(k=1\\) 退化为单条 purged \\(K\\) 折；要分布必须 \\(k\\ge 2\\)。</li><li>路径分布回答稳不稳，PBO 回答搜索过不过拟合，walk-forward 回答可不可按时间部署，DSR 回答夏普在尝试次数下还剩多少。</li><li>交错路径不是交易模拟；禁止从路径里挑最好的一条当样本外。</li><li>出处：López de Prado, <em>Advances in Financial Machine Learning</em>, Wiley, 2018，第 12 章；PBO/CSCV 见 Bailey, Borwein, López de Prado and Zhu, <em>Journal of Computational Finance</em>, 2017，综述见 <a href="/quant/cpcv">组合过拟合 CPCV</a>。</li></ul>',2))])}const k=n(h,[["render",s]]);export{b as __pageData,k as default};
